import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Glyphs","description":"","frontmatter":{},"headers":[],"relativePath":"components/glyphs.md","filePath":"components/glyphs.md"}'),s={name:"components/glyphs.md"};function r(l,e,i,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="glyphs" tabindex="-1">Glyphs <a class="header-anchor" href="#glyphs" aria-label="Permalink to &quot;Glyphs&quot;">​</a></h1><p>Glyphs is a grid of symbols or emoji to pick one from.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in a picker, inside a panel or a popover. With <code>row</code> the symbols run in one line instead, for a toolbar. When the same symbol appears twice, pass <code>selected</code> to tell them apart by position. A choice of colors is a <a href="./color-grid">ColorGrid</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td>required</td><td>The symbols, one per cell</td></tr><tr><td><code>value</code></td><td></td><td>The selected symbol</td></tr><tr><td><code>onselect</code></td><td>required</td><td>Called with the symbol and its position</td></tr><tr><td><code>label</code></td><td></td><td><code>(symbol, i)</code> to the name of a cell (default: the symbol)</td></tr><tr><td><code>selected</code></td><td></td><td><code>(symbol, i)</code> to whether a cell is selected</td></tr><tr><td><code>row</code></td><td><code>false</code></td><td>One line that scrolls sideways</td></tr><tr><td><code>columns</code></td><td><code>8</code></td><td>The number of columns; in a row, a cell is as wide as one</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p><code>columns</code> columns (eight by default) divide the width, at most a square, gap-2xs apart; a cell is as tall as a button and its symbol takes the size of the h1 role. In a row, a cell is as wide as a column of the grid, so that a band above a grid with the same <code>columns</code> and the same width lines up with it. A cell has the raise surface on hover; the selected cell has <code>--kata-color-raise-2</code> and a line of <code>--kata-color-blue-ink</code> inside, and reports <code>aria-pressed</code>. The focus ring is drawn inside. The font of the symbols is <code>--kata-glyph-font</code>, set by the container (an emoji font, for example).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/glyphs/" title="Glyphs" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/glyphs/" target="_blank" rel="noopener">Glyphs</a></figcaption></figure>',10)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
